with metrics as (select *, count(unit_price) over w_running as last4_count_unit_price, avg(unit_price) over w_running as last4_avg_unit_price, max(unit_price) over w_running as last4_max_unit_price, ntile(5) over (order by unit_price desc, id) as unit_price_bucket from order_items window w_running as (partition by product_id, order_id order by unit_price, id rows between 3 preceding and current row)) select id, order_id, product_id, unit_price, last4_avg_unit_price, last4_max_unit_price from metrics order by product_id;
